:root {
            --shadowSize: 10px;
            --shadowColor: #afafaf;
        }

        .rstab-container {
            display: flex;
            justify-content: center;
            margin: 0 0 40px 0;
            gap: 60px;
            font-family: Noto Sans, sans-serif;
        }

      
        .rsbox {
            display: none; /* Hidden by default */
            position: relative;
            width: 60%;
            margin: 40px auto;
            padding: 40px;
            box-shadow: 0 0 var(--shadowSize) var(--shadowColor);
            background-color: #fff;
            border-radius: 8px;
            box-sizing: border-box;
           
        }

        .rsbox.active {
            display: block; /* Show the active tab's content */
        }

        #box1:before {
            content: "";
            position: absolute;
            top: 0%;
            left: 40%;
            width: 30px;
            height: 30px;
            background-color: #fff;
            box-shadow: 0 0 var(--shadowSize) var(--shadowColor);
            transform: translate(50%, -50%) rotate(-45deg);
            clip-path: polygon(
                calc(var(--shadowSize) * -1) calc(var(--shadowSize) * -1), 
                calc(100% + var(--shadowSize)) calc(var(--shadowSize) * -1), 
                calc(100% + var(--shadowSize)) calc(100% + var(--shadowSize))
            );
        }

        .rsbox:before {
            content: "";
            position: absolute;
            top: 0%;
            left: 53.5%;
            width: 30px;
            height: 30px;
            background-color: #fff;
            box-shadow: 0 0 var(--shadowSize) var(--shadowColor);
            transform: translate(50%, -50%) rotate(-45deg);
            clip-path: polygon(
                calc(var(--shadowSize) * -1) calc(var(--shadowSize) * -1), 
                calc(100% + var(--shadowSize)) calc(var(--shadowSize) * -1), 
                calc(100% + var(--shadowSize)) calc(100% + var(--shadowSize))
            );
        }

        /* Highlight the active tab */
       

